```st
FUNCTION_BLOCK FB
VAR_INPUT
    enqueue  : BOOL;
    dequeue  : BOOL;
    reset    : BOOL;
    capacity : DINT;
END_VAR
VAR_OUTPUT
    elementCount : DINT;
    status       : WORD;
END_VAR
VAR_IN_OUT
    item   : DINT;
    buffer : ARRAY[1..4] OF DINT;
END_VAR
VAR
    head        : DINT := 1;
    tail        : DINT := 1;
    prevEnqueue : BOOL := FALSE;
    prevDequeue : BOOL := FALSE;
    prevReset   : BOOL := FALSE;
END_VAR

status := 16#0000;

IF reset AND NOT prevReset THEN
    head := 1;
    tail := 1;
    elementCount := 0;
    prevEnqueue := enqueue;
    prevDequeue := dequeue;
    prevReset := reset;
    RETURN;
END_IF

IF enqueue AND NOT prevEnqueue THEN
    IF elementCount >= capacity THEN
        status := 16#8002;
    ELSE
        buffer[DINT_TO_INT(tail)] := item;
        IF tail >= capacity THEN
            tail := 1;
        ELSE
            tail := tail + 1;
        END_IF
    END_IF;
END_IF;

IF dequeue AND NOT prevDequeue THEN
    IF elementCount <= 0 THEN
        status := 16#8001;
    ELSE
        item := buffer[DINT_TO_INT(head)];
        IF head >= capacity THEN
            head := 1;
        ELSE
            head := head + 1;
        END_IF;
    END_IF;
END_IF;

IF tail >= head THEN
    elementCount := tail - head;
ELSE
    elementCount := capacity - head + tail + 1;
END_IF;

prevEnqueue := enqueue;
prevDequeue := dequeue;
prevReset := reset;
END_FUNCTION_BLOCK
```

